// -*- coding: utf-8 -*-
// Adversarial-ambient corpus (pipeline e5b9c231 Phase 3, AC1): route hostile
// ambient graphics/text-state fixtures through the ContentStreamEditor text
// injector and assert -- with the shared VISUAL oracle -- that BOTH the edited
// element AND an untouched neighbour render correctly. These guard the
// state-continuity class (the "-100 Tz" mirror family) against the ambient
// states most likely to produce the next escape.
//
// Fixtures generated by tests/fixtures/gen_adversarial_ambient_corpus.py.
#include <gtest/gtest.h>
#include "textedit/ContentStreamEditor.h"
#include "textedit/TextEditModel.h"
#include "core/Document.h"
#include "core/Page.h"
#include "core/MuPdfContext.h"
#include "support/VisualOracle.h"

#include <filesystem>
#include <memory>
#include <string>
#include <vector>

using namespace pdfe::textedit;
using namespace pdfe::core;
using pdfe::testsupport::Glyph;
using pdfe::testsupport::lineContaining;
using pdfe::testsupport::isLeftToRight;

namespace {

// Edit "EDITME" -> "EDITED" in the given fixture, save, and return the output path.
std::filesystem::path editFixture(const std::string& fixtureName) {
    auto ctx = std::make_shared<MuPdfContext>();
    std::filesystem::path fx =
        std::filesystem::path(TEST_FIXTURES_DIR) / fixtureName;
    EXPECT_TRUE(std::filesystem::exists(fx)) << fx.string();
    auto doc = Document::open(ctx, fx);
    EXPECT_NE(doc, nullptr);
    auto page = doc->page(0);
    EXPECT_NE(page, nullptr);

    auto blocks = page->extractText();
    TextEditModel model(blocks);
    std::vector<TextSpan> spans;
    for (int i = 0; i < model.spanCount(); ++i) spans.push_back(model.span(i));
    int target = -1;
    for (int i = 0; i < static_cast<int>(spans.size()); ++i)
        if (spans[i].text.find(U"EDITME") != std::u32string::npos) { target = i; break; }
    EXPECT_GE(target, 0) << "fixture must contain an 'EDITME' span";

    ContentStreamEditor editor(ctx.get());
    std::vector<std::pair<int, std::u32string>> mods{{target, U"EDITED"}};
    editor.applyEdits(page.get(), doc.get(), spans, mods);

    std::filesystem::path out =
        std::filesystem::temp_directory_path() / ("pdfe_adv_" + fixtureName);
    doc->saveAs(out);
    return out;
}

// Assert the edit landed (EDITED present, upright) and the neighbour survived.
void expectEditAndNeighborOk(const std::string& fixtureName) {
    std::filesystem::path out = editFixture(fixtureName);
    auto edited = lineContaining(out, U"EDITED");
    ASSERT_FALSE(edited.empty())
        << fixtureName << ": edited 'EDITED' text not found -- edit dropped or "
           "clipped away by the ambient state";
    EXPECT_TRUE(isLeftToRight(edited))
        << fixtureName << ": edited text is mirrored (ambient state leaked)";

    auto nbr = lineContaining(out, U"KEEPME");
    ASSERT_FALSE(nbr.empty())
        << fixtureName << ": neighbour 'KEEPME' vanished after the edit";
    EXPECT_TRUE(isLeftToRight(nbr))
        << fixtureName << ": neighbour mirrored/corrupted by the edit";
}

} // namespace

// Row 1: ambient CMYK (`k`) text fill. Plus a colour oracle: the edited text
// must not collapse to black under the ambient cyan fill (the exact sibling of
// the shipped grey-fill loss, in a colourspace no fixture used to exercise).
TEST(AdversarialAmbientCorpus, CmykFill_EditSurvives) {
    expectEditAndNeighborOk("adv_cmyk_fill.pdf");
    auto out = editFixture("adv_cmyk_fill.pdf");
    auto edited = lineContaining(out, U"EDITED");
    ASSERT_FALSE(edited.empty());
    // Cyan (1 0 0 0 k) -> low red, high green/blue. A black result (all low)
    // would mean the CMYK fill was lost on edit.
    const uint32_t argb = edited.front().argb;
    const int g = (argb >> 8) & 0xFF, b = argb & 0xFF;
    EXPECT_TRUE(g > 0x60 || b > 0x60)
        << "edited text collapsed toward black under ambient CMYK fill "
        << "(argb=" << std::hex << argb << ")";
}

// Row 3: dangling/unbalanced `q` (leaked graphics state).
TEST(AdversarialAmbientCorpus, DanglingQ_EditSurvives) {
    expectEditAndNeighborOk("adv_dangling_q.pdf");
}

// Row 4: active clip path around the edit region (edit must not be clipped away).
TEST(AdversarialAmbientCorpus, ClipPath_EditNotClippedAway) {
    expectEditAndNeighborOk("adv_clip_path.pdf");
}
